<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue';
import { apiRequest } from '../lib/api';
import { useAppStore } from '../stores/app';
interface Award { id?: string; programmeSlug?: string; code: string; name: string; description?: string; category?: string; status?: string; achievementMetric?: string; condition?: unknown; levels?: unknown; effectiveFrom?: string; backgroundAsset?: Record<string, unknown>; printSpec?: Record<string, unknown>; template?: { elements?: unknown[] }; }
const store = useAppStore(); const programme = ref(store.currentProgramme || store.programmes[0]?.slug || ''); const items = ref<Award[]>([]); const selected = ref<Award | null>(null); const message = ref(''); const assets = ref<any[]>([]); const requests = ref<any[]>([]); const issuances = ref<any[]>([]);
const form = reactive({ code: '', name: '', description: '', category: 'HUNTER', achievementMetric: 'QSO_COUNT', effectiveFrom: '', condition: '{\n  "kind": "AND",\n  "conditions": [{ "kind": "QSO_COUNT", "operator": "GTE", "value": 10 }]\n}', levels: '[{ "id": "level-10", "name": "10 contacts", "threshold": 10 }]', backgroundKey: '', backgroundType: 'image/png', width: 2481, height: 3508, page: 'A4', orientation: 'PORTRAIT', dpi: 300 });
function edit(item: Award | null): void { selected.value = item; const background: any = item?.backgroundAsset || {}; const print: any = item?.printSpec || {}; Object.assign(form, { code: item?.code || '', name: item?.name || '', description: item?.description || '', category: item?.category || 'HUNTER', achievementMetric: item?.achievementMetric || 'QSO_COUNT', effectiveFrom: item?.effectiveFrom ? String(item.effectiveFrom).slice(0, 16) : '', condition: JSON.stringify(item?.condition || { kind: 'AND', conditions: [{ kind: 'QSO_COUNT', operator: 'GTE', value: 10 }] }, null, 2), levels: JSON.stringify(item?.levels || [{ id: 'level-10', name: '10 contacts', threshold: 10 }], null, 2), backgroundKey: background.objectKey || '', backgroundType: background.mediaType || 'image/png', width: background.widthPx || 2481, height: background.heightPx || 3508, page: print.page || 'A4', orientation: print.orientation || 'PORTRAIT', dpi: print.dpi || 300 }); }
async function load(selectedId?: string | Event): Promise<void> { if (!programme.value) return; const id = typeof selectedId === 'string' ? selectedId : undefined; const [awardData, assetData, requestData, issuanceData] = await Promise.all([apiRequest<{ items: Award[] }>(`/v1/awards?programme=${encodeURIComponent(programme.value)}&pageSize=100`), apiRequest<{ items: any[] }>('/v1/awards/assets?pageSize=100'), apiRequest<{ items: any[] }>('/v1/awards/requests?pageSize=100'), apiRequest<{ items: any[] }>('/v1/awards/issuances?pageSize=100')]); items.value = awardData.items || []; assets.value = assetData.items || []; requests.value = requestData.items || []; issuances.value = issuanceData.items || []; if (id) edit(items.value.find(item => item.id === id) || null); }
async function save(): Promise<void> { try { const saved = await apiRequest<Award>('/v1/awards', { method: 'POST', body: JSON.stringify({ awardId: selected.value?.id, programmeSlug: programme.value, code: form.code, name: form.name, description: form.description, category: form.category, achievementMetric: form.achievementMetric, condition: JSON.parse(form.condition), levels: JSON.parse(form.levels), backgroundAsset: { kind: 'BACKGROUND', name: `${form.name} background`, objectKey: form.backgroundKey, mediaType: form.backgroundType, widthPx: Number(form.width), heightPx: Number(form.height) }, printSpec: { page: form.page, orientation: form.orientation, dpi: Number(form.dpi) }, template: { elements: [] } }), headers: { 'Idempotency-Key': crypto.randomUUID() } }); message.value = 'Award draft saved.'; await load(saved.id); } catch (error) { message.value = error instanceof Error ? error.message : 'Invalid award definition.'; } }
async function action(actionName: string, decision?: string): Promise<void> { if (!selected.value?.id) return; try { if (actionName === 'publish' && !form.effectiveFrom) throw new Error('Choose an effective date before publishing.'); await apiRequest(`/v1/awards/${encodeURIComponent(selected.value.id)}/${actionName}`, { method: 'POST', body: JSON.stringify(actionName === 'review' ? { decision, reviewerId: store.account?.id } : actionName === 'publish' ? { effectiveFrom: form.effectiveFrom, publisherId: store.account?.id } : {}) }); message.value = `Award ${actionName === 'publish' ? 'published' : `${actionName}ed`}.`; await load(selected.value.id); } catch (error) { message.value = error instanceof Error ? error.message : 'Award action failed.'; } }
watch(programme, () => { store.currentProgramme = programme.value; load(); }); onMounted(() => load());
</script>

<template><section class="page-heading"><div><p class="eyebrow">ACTIVITY & CERTIFICATES</p><h1>Awards and certificates</h1><p class="muted">Programme-owned hunter and activator awards with explicit publication and print profiles.</p></div><button class="primary" @click="edit(null)">New award draft</button></section><div class="toolbar"><label class="toolbar-field">Programme<select v-model="programme"><option v-for="item in store.programmes" :key="item.slug" :value="item.slug">{{ item.name }}</option></select></label><button class="secondary" @click="load">Refresh</button></div><div v-if="message" class="notice" role="status">{{ message }}</div><div class="split-layout"><article class="panel"><div class="panel-heading"><h2>Award definitions</h2></div><div class="table-list"><button v-for="item in items" :key="item.id" class="table-row" :class="{ selected: selected?.id === item.id }" @click="edit(item)"><span><strong>{{ item.name }}</strong><small>{{ item.code }} · {{ item.category }} · {{ item.programmeSlug }}</small></span><span class="status-pill" :class="(item.status || '').toLowerCase()">{{ item.status }}</span></button><p v-if="!items.length" class="muted empty">No awards configured for this programme.</p></div></article><article class="panel"><div class="panel-heading"><h2>{{ selected ? selected.name : 'New award draft' }}</h2></div><form class="form-grid" @submit.prevent="save"><label>Code<input v-model="form.code" required></label><label>Name<input v-model="form.name" required></label><label>Category<select v-model="form.category"><option>HUNTER</option><option>ACTIVATOR</option></select></label><label>Achievement metric<select v-model="form.achievementMetric"><option>QSO_COUNT</option><option>ACTIVATION_COUNT</option><option>UNIQUE_CALLSIGNS</option><option>UNIQUE_ENTITIES</option></select></label><label class="wide">Description<textarea v-model="form.description"></textarea></label><label>Effective from<input v-model="form.effectiveFrom" type="datetime-local"></label><label>Background object key<input v-model="form.backgroundKey" placeholder="awards/programme/background.png"></label><label>Background width<input v-model.number="form.width" type="number" min="1"></label><label>Background height<input v-model.number="form.height" type="number" min="1"></label><label>Page<select v-model="form.page"><option>A4</option><option>LETTER</option></select></label><label>Orientation<select v-model="form.orientation"><option>PORTRAIT</option><option>LANDSCAPE</option></select></label><label>Resolution<input v-model.number="form.dpi" type="number" min="150"></label><label class="wide">Condition JSON<textarea v-model="form.condition" class="code-editor"></textarea></label><label class="wide">Levels JSON<textarea v-model="form.levels" class="code-editor"></textarea></label><div class="form-actions wide"><button class="primary" type="submit">Save award draft</button><button v-if="selected && ['DRAFT','CHANGES_REQUESTED'].includes(selected.status || '')" class="secondary" type="button" @click="action('submit')">Submit for review</button><button v-if="selected?.status === 'UNDER_REVIEW'" class="approve" type="button" @click="action('review', 'APPROVED')">Approve</button><button v-if="selected?.status === 'UNDER_REVIEW'" class="reject" type="button" @click="action('review', 'CHANGES_REQUESTED')">Request changes</button><button v-if="selected?.status === 'APPROVED'" class="primary" type="button" @click="action('publish')">Publish</button></div></form></article></div><div class="dashboard-grid"><article class="panel"><div class="panel-heading"><h2>Registered assets</h2></div><div class="table-list"><div v-for="asset in assets" :key="asset.id" class="table-row"><span><strong>{{ asset.name }}</strong><small>{{ asset.kind }} · {{ asset.objectKey }}</small></span><span>{{ asset.widthPx }} × {{ asset.heightPx }} px</span></div></div></article><article class="panel"><div class="panel-heading"><h2>Requests and issuances</h2></div><div class="table-list"><div v-for="request in requests" :key="request.id" class="table-row"><span><strong>{{ request.callsign }} · {{ request.personName }}</strong><small>{{ request.programmeSlug }} · {{ request.levelId }}</small></span><span class="status-pill">{{ request.status }}</span></div><div v-for="issuance in issuances" :key="issuance.id" class="table-row"><span><strong>{{ issuance.awardName }}</strong><small>{{ issuance.callsign }} · {{ issuance.levelId }}</small></span><span>{{ issuance.dateObtained }}</span></div><p v-if="!requests.length && !issuances.length" class="muted empty">No requests or issuances yet.</p></div></article></div></template>
